import { useState } from 'react';
import './App.css';

const avatarOptions = [
  { id: 'coral', label: 'Coral', initials: 'C', className: 'avatar--coral' },
  { id: 'teal', label: 'Teal', initials: 'T', className: 'avatar--teal' },
  { id: 'stone', label: 'Stone', initials: 'S', className: 'avatar--stone' },
  { id: 'navy', label: 'Navy', initials: 'N', className: 'avatar--navy' },
];

function App() {
  const [formData, setFormData] = useState({
    username: '',
    bio: '',
    avatarId: avatarOptions[0].id,
  });
  const [profile, setProfile] = useState(null);

  const selectedAvatar =
    avatarOptions.find((option) => option.id === formData.avatarId) ||
    avatarOptions[0];

  const handleChange = (event) => {
    const { name, value } = event.target;

    setFormData((current) => ({
      ...current,
      [name]: value,
    }));
  };

  const handleAvatarSelect = (avatarId) => {
    setFormData((current) => ({
      ...current,
      avatarId,
    }));
  };

  const handleSubmit = (event) => {
    event.preventDefault();

    const username = formData.username.trim();
    const bio = formData.bio.trim();

    if (!username || !bio) {
      return;
    }

    setProfile({
      username,
      bio,
      avatar: selectedAvatar,
    });
  };

  return (
    <main className="app">
      <section className="card">
        <div className="card-header">
          <p className="eyebrow">Account setup</p>
          <h1>Create your profile</h1>
          <p className="subcopy">
            A very basic sign up for now. Media history and community features
            are shown as placeholders until they are built.
          </p>
        </div>

        <form className="form" onSubmit={handleSubmit}>
          <label className="field">
            <span>Username</span>
            <input
              name="username"
              type="text"
              placeholder="moviefan"
              value={formData.username}
              onChange={handleChange}
              maxLength="24"
              required
            />
          </label>

          <label className="field">
            <span>Bio</span>
            <textarea
              name="bio"
              placeholder="Share a short note about what you like."
              value={formData.bio}
              onChange={handleChange}
              rows="4"
              maxLength="160"
              required
            />
          </label>

          <fieldset className="field avatar-field">
            <legend>Avatar</legend>

            <div className="avatar-list">
              {avatarOptions.map((option) => {
                const isSelected = option.id === formData.avatarId;

                return (
                  <button
                    key={option.id}
                    type="button"
                    className={`avatar-option${isSelected ? ' is-selected' : ''}`}
                    onClick={() => handleAvatarSelect(option.id)}
                    aria-pressed={isSelected}
                  >
                    <span
                      className={`avatar-swatch ${option.className}`}
                      aria-hidden="true"
                    >
                      {option.initials}
                    </span>
                    <span>{option.label}</span>
                  </button>
                );
              })}
            </div>
          </fieldset>

          <button className="primary-button" type="submit">
            {profile ? 'Update profile' : 'Create profile'}
          </button>
        </form>

        <section className="summary" aria-label="Profile summary">
          <div
            className={`summary-avatar ${(
              profile?.avatar || selectedAvatar
            ).className}`}
            aria-hidden="true"
          >
            {(profile?.avatar || selectedAvatar).initials}
          </div>

          <div>
            <h2>{profile ? `@${profile.username}` : '@your_name'}</h2>
            <p>
              {profile
                ? profile.bio
                : 'Your username, bio, and avatar preview will appear here.'}
            </p>
            {profile ? (
              <p className="status" role="status">
                Profile created locally.
              </p>
            ) : null}
          </div>
        </section>

        <section className="placeholders" aria-label="Upcoming features">
          <h2>Coming later</h2>
          <p>Media history logging placeholder.</p>
          <p>Community interactions placeholder.</p>
          <p>Reviews and activity feed placeholder.</p>
        </section>
      </section>
    </main>
  );
}

export default App;
